	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		EmploymentContract
	 */
		public EmploymentContract createEmploymentContract( CreateEmploymentContractCommand command ) {

		EmploymentContract entity = new EmploymentContract();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setEmploymentContractId( command.getEmploymentContractId() );
            entity.setContractNumber( command.getContractNumber() );
            entity.setStartDate( command.getStartDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setWorkHoursPerWeek( command.getWorkHoursPerWeek() );
            entity.setEmploymentType( command.getEmploymentType() );
            entity.setStatus( command.getStatus() );
            entity.setPayFrequency( command.getPayFrequency() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of EmploymentContract {0} ", entity.toString() );

		return entity;
	}

